"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["65365"],{36706(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.documento_exigido.fato_da_isencao_em_outra_finalidade","status":422,"titulo":"Fato do formul\xe1rio de isen\xe7\xe3o citado por documento de outro formul\xe1rio"},"descricao":{"codigo":"uniplus.selecao.documento_exigido.fato_da_isencao_em_outra_finalidade","requisitos":[],"oQueAconteceu":["Um fato que vem do formul\xe1rio de isen\xe7\xe3o de taxa s\xf3 pode ser citado por documento exigido no\\npr\xf3prio formul\xe1rio de isen\xe7\xe3o. A condi\xe7\xe3o do documento apontado cita um fato desse formul\xe1rio,\\nmas o documento pertence a outro formul\xe1rio (inscri\xe7\xe3o ou habilita\xe7\xe3o, ou a nenhum). O\\nformul\xe1rio de habilita\xe7\xe3o, por exemplo, usa s\xf3 fatos do formul\xe1rio de inscri\xe7\xe3o.","A confer\xeancia olha o formul\xe1rio do documento, e n\xe3o a fase, porque a inscri\xe7\xe3o e a isen\xe7\xe3o\\npodem dividir a mesma fase. Considera-se que o fato vem do formul\xe1rio de isen\xe7\xe3o quando algum\\ncampo desse formul\xe1rio o coleta, ou quando o fato depende de um que o coleta.","O fato pode vir de duas origens: da condi\xe7\xe3o do documento ou de um campo do grupo repet\xedvel\\npelo qual a exig\xeancia se repete, quando esse campo \xe9 coletado no formul\xe1rio de isen\xe7\xe3o. Na\\nsegunda, a condi\xe7\xe3o do documento n\xe3o \xe9 a causa.","Ela acontece na defini\xe7\xe3o dos documentos exigidos, na aplica\xe7\xe3o de um modelo de formul\xe1rio e,\\ncom o cat\xe1logo de fatos, na publica\xe7\xe3o e na retifica\xe7\xe3o em ato \xfanico. Vem depois de\\n[`ponto_resolucao_fora_do_cronograma`](/erros/uniplus.selecao.documento_exigido.ponto_resolucao_fora_do_cronograma)\\ne de\\n[`fato_resolvido_em_fase_posterior`](/erros/uniplus.selecao.documento_exigido.fato_resolvido_em_fase_posterior)."],"comoResolver":["A mensagem de detalhe nomeia o fato. Conforme a origem:","- se o fato est\xe1 numa condi\xe7\xe3o do documento, troque a condi\xe7\xe3o por um fato conhecido no\\n  formul\xe1rio a que o documento pertence, ou passe o documento para o formul\xe1rio de isen\xe7\xe3o,\\n  se for ali que ele deve ser pedido;\\n- se o fato \xe9 de campo de um grupo repet\xedvel coletado no formul\xe1rio de isen\xe7\xe3o, trocar a\\n  condi\xe7\xe3o n\xe3o resolve: passe a exig\xeancia para o formul\xe1rio de isen\xe7\xe3o, vincule-a a um grupo\\n  repet\xedvel coletado no formul\xe1rio dela ou retire a repeti\xe7\xe3o por grupo."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo","Aplica\xe7\xe3o de modelo de formul\xe1rio","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Documento exigido"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);